INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q4553468', '1797 Riobamba earthquake (Ecuador)', 'The 1797 Riobamba earthquake occurred at 12:30 UTC on 4 February. It devastated the city of Riobamba and many other cities in the Interandean valley, causing between 6,000 and 40,000 casualties.', 1797, 2, 4, NULL, NULL, NULL, 'day', '4 February 1797', 51, 'https://en.wikipedia.org/wiki/1797_Riobamba_earthquake'),
  ('Q3181490', 'Battle of Camino Real', 'The Battle of Camino Real, was the first battle in the Ecuadorian War of Independence, that took place on 9 November 1820. The battle was fought between Royalist soldiers in support of the Spanish Empire, and the Patriot forces of the Free Province of Guayaquil, who won the battle.', 1820, 11, 9, NULL, NULL, NULL, 'day', '9 November 1820', 37, 'https://en.wikipedia.org/wiki/Battle_of_Camino_Real'),
  ('Q3181491', 'First Battle of Huachi Grande', 'The First Battle of Huachi was the second battle in the Ecuadorian War of Independence, that took place on 22 November 1820 near Ambato, Ecuador. The battle was fought between Royalist soldiers in support of the Spanish Empire, and the Patriot forces of the Free Province of Guayaquil, who suffered a serious defeat.', 1820, 11, 22, NULL, NULL, NULL, 'day', '22 November 1820', 34, 'https://en.wikipedia.org/wiki/First_Battle_of_Huachi'),
  ('Q5334383', 'Ecuadorian War of Independence', 'The Quito Campaign (1820–1822), sometimes referred to as the Ecuadorian War of Independence, was a series of military operations during the Spanish American wars of independence that ended Spanish rule over the Real Audiencia of Quito. The territory was incorporated into Gran Colombia, from which it seceded as the Republic of Ecuador in 1830.', 1820, NULL, NULL, 1823, NULL, NULL, 'year', '1820–1823', 45, 'https://en.wikipedia.org/wiki/Ecuadorian_War_of_Independence'),
  ('Q2890399', 'Battle of Yaguachi', 'The Battle of Yaguachi or Battle of Cone was a military confrontation that occurred on 19 August 1821 between Guayaquil independence troops and Grancolombian reinforcements, led by Antonio José de Sucre, against Royalist troops led by Colonel Francisco González. The battle was fought near the city of Yaguachi, current Province of Guayas in Ecuador, and was a victory for the Patriots which ensured the definitive independence of the Free Province of Guayaquil.', 1821, 8, 19, NULL, NULL, NULL, 'day', '19 August 1821', 39, 'https://en.wikipedia.org/wiki/Battle_of_Yaguachi'),
  ('Q3020018', 'Second Battle of Huachi', 'The Second Battle of Huachi was a confrontation that occurred on 12 September 1821 between pro-independence troops led by General Antonio José de Sucre and Royalist troops led by General Melchor Aymerich, president of the Real Audiencia of Quito. Sucre, after having won the Battle of Yaguachi on 19 August, advanced towards Quito.', 1821, 9, 12, NULL, NULL, NULL, 'day', '12 September 1821', 34, 'https://en.wikipedia.org/wiki/Second_Battle_of_Huachi'),
  ('Q1402751', 'Battle of Pichincha', 'The Battle of Pichincha took place on 24 May 1822, on the slopes of the Pichincha volcano, 3,500 meters above sea-level, right next to the city of Quito, in modern Ecuador. The encounter, fought in the context of the Spanish American wars of independence, pitted a Patriot army under General Antonio José de Sucre against a Royalist army commanded by Field Marshal Melchor Aymerich.', 1822, 5, 24, NULL, NULL, NULL, 'day', '24 May 1822', 55, 'https://en.wikipedia.org/wiki/Battle_of_Pichincha'),
  ('Q747266', 'Battle of Tarqui', 'The Battle of Tarqui, also known as the Battle of Portete de Tarqui, took place on 27 February 1829 at Tarqui, near Cuenca, today part of Ecuador. It was fought between troops from Gran Colombia, commanded by Antonio José de Sucre, and Peruvian troops under José de La Mar.', 1829, 2, 26, NULL, NULL, NULL, 'day', '26 February 1829', 34, 'https://en.wikipedia.org/wiki/Battle_of_Tarqui'),
  ('Q17631986', 'Pando–Noboa Treaty', 'The Colombian–Peruvian territorial dispute was a territorial dispute between Colombia and Peru, which, until 1916, also included Ecuador. The dispute had its origins on each country''s interpretation of what Real Cedulas Spain used to precisely define its possessions in the Americas.', 1832, 7, 12, NULL, NULL, NULL, 'day', '12 July 1832', 30, 'https://en.wikipedia.org/wiki/Pando%E2%80%93Noboa_Treaty'),
  ('Q10746587', 'March Revolution (Ecuador)', 'The March Revolution (Revolución marcista or Revolución de Marzo) or Revolution of Forty-Five (Revolución de 1845) began on 6 March 1845, when the people of Guayaquil under the leadership of General António Elizalde and Lieutenant-Colonel Fernándo Ayarza revolted against the government of Juan José Flores. The people took the artillery barracks of Guayaquil along with other military and civilian supporters, including the guard on duty.', 1843, NULL, NULL, 1845, 6, 17, 'year', '1843 – 17 June 1845', 37, 'https://en.wikipedia.org/wiki/March_Revolution_(Ecuador)'),
  ('Q5685354', 'Treaty of Mapasingue', 'The First Ecuadorian–Peruvian War took place between 1857 and 1860. The conflict began when Ecuador attempted to sell Amazon basin land claimed by Peru in order to settle a debt with British creditors.', 1860, 1, 25, NULL, NULL, NULL, 'day', '25 January 1860', 30, 'https://en.wikipedia.org/wiki/Treaty_of_Mapasingue'),
  ('Q3118971', 'Ecuadorian–Colombian War', 'The Ecuadorian–Colombian War (Spanish: Guerra ecuatoriano-colombiana) was a series of armed conflicts waged between the current republics of Colombia and Ecuador between 1862 and 1863.', 1863, NULL, NULL, 1863, 12, 30, 'year', '1863', 39, 'https://en.wikipedia.org/wiki/Ecuadorian%E2%80%93Colombian_War'),
  ('Q742813', 'Chincha Islands War', 'The Chincha Islands War, also known as Spanish–South American War (Spanish: Guerra hispano-sudamericana), was a series of coastal and naval battles between Spain and its former colonies of Peru, Chile, Ecuador, and Bolivia from 1865 to 1879. The conflict began with Spain''s seizure of the guano-rich Chincha Islands in one of a series of attempts by Spain, under Isabella II, to reassert its influence over its former South American colonies.', 1864, 4, 14, 1866, NULL, NULL, 'day', '14 April 1864 – 1866', 61, 'https://en.wikipedia.org/wiki/Chincha_Islands_War'),
  ('Q17631978', 'García–Herrera Treaty', 'Treaty of 1890 between Peru and Ecuador.', 1890, 5, 2, NULL, NULL, NULL, 'day', '2 May 1890', 30, 'https://en.wikipedia.org/wiki/Garc%C3%ADa%E2%80%93Herrera_Treaty'),
  ('Q1822896', 'Liberal Revolution of Ecuador', 'The Liberal Revolution of 1895 took place in Ecuador, and was a period of radical social and political upheaval. The Revolution started on June 5, 1895 and ultimately resulted in the overthrow of the conservative government, which had ruled Ecuador for several decades, by the Radical Liberals, led by Eloy Alfaro.', 1895, 6, NULL, 1912, 1, 28, 'month', 'June 1895 – 28 January 1912', 39, 'https://en.wikipedia.org/wiki/Liberal_Revolution_of_1895'),
  ('Q4558519', '1906 Ecuador-Colombia earthquake', 'The 1906 Ecuador–Colombia earthquake occurred at 10:36:10 (UTC+5) on Wednesday, January 31, 1906, off the coast of Ecuador, near Esmeraldas. The earthquake had a moment magnitude of 8.8 and triggered a destructive tsunami that caused at least 500 casualties on the coast of Colombia.', 1906, 1, 31, NULL, NULL, NULL, 'day', '31 January 1906', 47, 'https://en.wikipedia.org/wiki/1906_Ecuador%E2%80%93Colombia_earthquake'),
  ('Q77457310', 'War of the Generals', 'The War of the Generals was a civil war fought in Ecuador from 1911 to 1912. Its causes laid in liberal opposition to the authoritarian reign of Eloy Alfaro.', 1911, 12, 28, 1912, 1, 18, 'day', '28 December 1911 – 18 January 1912', 26, 'https://en.wikipedia.org/wiki/War_of_the_Generals'),
  ('Q39080987', 'Ecuadorian Civil War of 1912–1914', 'The Ecuadorian Civil War of 1913–1916, or Concha Revolution, was an uprising against Ecuadorian President Leónidas Plaza in the Esmeraldas Province. Much of the province was destroyed in the process, but the government was ultimately able to re-assert control.', 1913, NULL, NULL, 1916, NULL, NULL, 'year', '1913–1916', 34, 'https://en.wikipedia.org/wiki/Ecuadorian_Civil_War_of_1913%E2%80%931916'),
  ('Q1712418', 'July Revolution (Ecuador)', 'The July Revolution (Revolución Juliana) was a civic-military movement in Ecuador that led to a coup on July 9, 1925. Spearheaded by the Military League, a group of young, progressive officers in the Ecuadorian Army, the coup resulted in the overthrow of President Gonzalo Córdova.', 1925, 7, 9, 1925, 7, 9, 'day', '9 July 1925', 37, 'https://en.wikipedia.org/wiki/July_Revolution_(Ecuador)'),
  ('Q18208081', 'Ecuadorian Civil War of 1932', 'The Ecuadorian Civil War was a war fought in August 1932 between supporters and opponents of president Isidro Ayora.', 1932, 8, 27, 1932, 9, 1, 'day', '27 August 1932 – 1 September 1932', 26, 'https://en.wikipedia.org/wiki/Ecuadorian_Civil_War_of_1932'),
  ('Q1500631', 'Ecuadorian–Peruvian War', 'The Second Ecuadorian–Peruvian War, usually called simply the Ecuadorian–Peruvian War, and known locally as the War of ''41 (Spanish: Guerra del 41), was a South American war fought between 5 July to 2 October of 1941. It was the first of three military conflicts between Ecuador and Peru during the 20th century.', 1942, 1, 31, 1942, 1, 29, 'day', '31 January 1942 – 29 January 1942', 62, 'https://en.wikipedia.org/wiki/Ecuadorian%E2%80%93Peruvian_War'),
  ('Q1801868', 'Rio Protocol', 'The Protocol of Peace, Friendship, and Boundaries between Peru and Ecuador, or Rio Protocol for short, was an international agreement signed in Rio de Janeiro, Brazil, on January 29, 1942, by the foreign ministers of Peru and Ecuador, with the participation of the United States, Brazil, Chile, and Argentina as guarantors. The Protocol was intended to finally resolve the long-running territorial dispute between the two countries, and brought about the official end of the Ecuadorian–Peruvian War of 1941–1942.', 1942, 1, 29, NULL, NULL, NULL, 'day', '29 January 1942', 52, 'https://en.wikipedia.org/wiki/Rio_Protocol'),
  ('Q774314', '1949 Pelileo earthquake', 'A magnitude 6.4 Ms earthquake struck Ecuador''s Tungurahua Province southeast of its capital Ambato and killed 5,050 people on August 5, 1949. The nearby villages of Guano, Patate, Pelileo, and Pillaro were destroyed, and the city of Ambato suffered heavy damage.', 1949, 8, 5, NULL, NULL, NULL, 'day', '5 August 1949', 52, 'https://en.wikipedia.org/wiki/1949_Ambato_earthquake'),
  ('Q116762709', 'El Carnavalazo', 'El Carnavalazo was a military coup in Ecuador led by Guillermo Rodríguez Lara that deposed the government of José María Velasco Ibarra on 15 February 1972, ending the fifth and last of the Velasquist presidencies. This event was popularly called "Carnavalazo" because it happened during the Ecuadorian carnival.', 1972, 2, 15, NULL, NULL, NULL, 'day', '15 February 1972', 34, 'https://en.wikipedia.org/wiki/El_Carnavalazo'),
  ('Q16663655', 'Masacre de Aztra', 'The Aztra massacre was a massacre of workers perpetrated by the National Police of Ecuador on October 18, 1977, at the Aztra ingenio, located in the La Troncal Canton, Cañar Province. The massacre left more than a hundred workers killed, mostly Indigenous, and occurred after the Indigenous workers started a strike to demand better wages.', 1977, 10, 18, NULL, NULL, NULL, 'day', '18 October 1977', 34, 'https://en.wikipedia.org/wiki/Aztra_massacre'),
  ('Q5942412', '1979 Tumaco earthquake', 'An earthquake occurred at 02:59 local time on 12 December 1979, with the epicenter just offshore from the border between Ecuador and Colombia, near the port city of Tumaco. With a moment magnitude of 8.2 and a maximum Mercalli intensity of IX (Violent), it triggered a major tsunami, which was responsible for most of the estimated 300–600 deaths.', 1979, 12, 12, NULL, NULL, NULL, 'day', '12 December 1979', 48, 'https://en.wikipedia.org/wiki/1979_Tumaco_earthquake'),
  ('Q1760930', 'Paquisha War', 'The Paquisha War, Fake Paquisha War or Paquisha incident (Spanish: Guerra de Paquisha, Conflicto del Falso Paquisha o Incidente de Paquisha) was a military clash that took place between January and February 1981 between Ecuador and Peru over the control of three watchposts. While Peru felt that the matter was already decided in the Ecuadorian–Peruvian War of 1941, Ecuador claimed that the Rio de Janeiro Protocol was not executable because a 78 km section of the border was not precisely defined.', 1981, 1, 28, 1981, 2, 5, 'day', '28 January 1981 – 5 February 1981', 55, 'https://en.wikipedia.org/wiki/Paquisha_War'),
  ('Q7669292', '1983 TAME 737-200 crash', 'TAME Flight 173, a Boeing 737-200 operated by Ecuador''s national airline TAME, flying on a domestic route from the now-closed Mariscal Sucre International Airport in Quito to Mariscal Lamar International Airport in Cuenca, crashed on 11 July 1983 into a hill during its final approach just 1 mile (1.6 km; 0.87 nmi) from its final destination, killing all 119 people on board. The crash was the deadliest crash in the history of TAME, and it remains as the deadliest aircraft accident in the history of Ecuador.', 1983, 7, 11, NULL, NULL, NULL, 'day', '11 July 1983', 45, 'https://en.wikipedia.org/wiki/TAME_Flight_173'),
  ('Q4583671', '1987 Ecuador earthquakes', 'The 1987 Ecuador earthquakes occurred over a six-hour period on March 6, 1987. The sequence of shocks measured 6.7, 7.1, and 6.0 on the moment magnitude scale.', 1987, 3, 6, NULL, NULL, NULL, 'day', '6 March 1987', 41, 'https://en.wikipedia.org/wiki/1987_Ecuador_earthquakes'),
  ('Q2337340', 'Cenepa War', 'The Cenepa War (26 January – 28 February 1995), also known as the Alto Cenepa War, was a brief and localized military conflict between Ecuador and Peru, fought over control of an area in the Ecuadorian territory (i.e. in the eastern side of the Cordillera del Cóndor, Province of Condorcanqui, Región Amazonas, Republic of Ecuador) near the border between the two countries.', 1995, 1, 26, 1995, 2, 28, 'day', '26 January 1995 – 28 February 1995', 53, 'https://en.wikipedia.org/wiki/Cenepa_War'),
  ('Q6164961', 'Cubana de Aviación Flight 389', 'Cubana de Aviación Flight 389 (CU389/CUB389) was a scheduled international passenger flight, flying from the former Mariscal Sucre International Airport in Quito to Havana''s José Martí International Airport, with a stopover at Simón Bolívar International Airport in Guayaquil, operated by Cuban flag carrier Cubana de Aviación. On 29 August 1998, the aircraft operating the domestic Quito-Guayaquil leg of the flight, a Russian-made Tupolev Tu-154M overran the runway, smashing buildings and crashed into a soccer field in Quito while taking off from the airport.', 1998, 8, 29, NULL, NULL, NULL, 'day', '29 August 1998', 47, 'https://en.wikipedia.org/wiki/Cubana_de_Aviaci%C3%B3n_Flight_389'),
  ('Q15991253', 'Brasilia Presidential Act', 'The Brasilia Presidential Act (Spanish: Acta Presidencial de Brasilia, Portuguese: Ato Presidencial de Brasília), also known as the Fujimori–Mahuad Treaty (Spanish: Tratado Fujimori–Mahuad), is an international treaty signed in Brasília by the then President of Ecuador, Jamil Mahuad and then President of Peru, Alberto Fujimori, which effectively put an end to the Ecuadorian–Peruvian territorial dispute.', 1998, 10, 26, NULL, NULL, NULL, 'day', '26 October 1998', 37, 'https://en.wikipedia.org/wiki/Brasilia_Presidential_Act'),
  ('Q4120789', '2000 Ecuadorian coup d''état', 'The 2000 Ecuadorian coup d''état took place on 21 January 2000 and resulted in President Jamil Mahuad being deposed, and replaced by Vice President Gustavo Noboa. The coup coalition brought together a short-lived junta composed by the country''s most powerful indigenous group, Confederation of Indigenous Nationalities of Ecuador (CONAIE), and a group of junior military officers led by Lieutenant Colonel Lucio Gutiérrez.', 2000, NULL, NULL, NULL, NULL, NULL, 'year', '2000', 39, 'https://en.wikipedia.org/wiki/2000_Ecuadorian_coup_d''%C3%A9tat'),
  ('Q17517025', 'August 2014 earthquake in Quito', 'On August 12, 2014, a magnitude 5.1 earthquake struck the South American country of Ecuador 23 km (14 mi) northeast of the capital, Quito, at a depth of 7.7 km (4.8 mi). The earthquake shook the city and surrounding areas, causing large dust clouds and prompting the temporary shutdown of the international airport.', 2014, 8, 12, NULL, NULL, NULL, 'day', '12 August 2014', 34, 'https://en.wikipedia.org/wiki/2014_Ecuador_earthquake'),
  ('Q23835355', '2016 Ecuador earthquake', 'The 2016 Ecuador earthquake occurred on April 16 at 18:58:37 ECT with a moment magnitude of 7.8 and a maximum Mercalli intensity of VIII (Severe). The very large thrust earthquake was centered approximately 27 km (17 mi) from the towns of Muisne and Pedernales in a sparsely populated part of the country, and 170 km (110 mi) from the capital Quito, where it was felt strongly.', 2016, 4, 16, NULL, NULL, NULL, 'day', '16 April 2016', 68, 'https://en.wikipedia.org/wiki/2016_Ecuador_earthquake'),
  ('Q28053338', 'Ecuadorian tax haven referendum, 2017', 'A referendum on banning politicians and civil servants from having bank accounts or companies based in tax havens was held in Ecuador on 19 February 2017, alongside general elections. The proposal was approved by voters, giving officials one year to transfer their assets or be removed from their posts.', 2017, 2, 19, NULL, NULL, NULL, 'day', '19 February 2017', 37, 'https://en.wikipedia.org/wiki/2017_Ecuadorian_tax_haven_referendum'),
  ('Q28949969', '2017 Peru floods', 'From December 2016 and continuing until May 2017, much of western and central South America was plagued by persistent heavy rain events. In Peru, one of the most severely impacted nations, it has been referred to as the 2017 Coastal Niño (Spanish: El Niño costero de 2017).', 2017, NULL, NULL, NULL, NULL, NULL, 'year', '2017', 43, 'https://en.wikipedia.org/wiki/2016%E2%80%9317_South_American_floods'),
  ('Q47495662', 'Ecuadorian referendum and popular consultation, 2018', 'A seven-part referendum and popular consultation was held in Ecuador on Sunday, February 4, 2018, to reform the constitution and consult citizens on issues of national importance. The consultation was announced on October 2, 2017, by President Lenin Moreno.', 2018, 2, 4, NULL, NULL, NULL, 'day', '4 February 2018', 39, 'https://en.wikipedia.org/wiki/2018_Ecuadorian_referendum_and_popular_consultation'),
  ('Q64031974', '2019 Peru earthquake', 'An earthquake measuring Mw 8.0 struck Peru and the surrounding areas on 26 May 2019 at 02:41 local time. It had a maximum perceived intensity of VII (Very strong) on the Modified Mercalli intensity scale in the towns of Yurimaguas and Lagunas.', 2019, 5, 26, NULL, NULL, NULL, 'day', '26 May 2019', 50, 'https://en.wikipedia.org/wiki/2019_Peru_earthquake'),
  ('Q69620172', '2019 Ecuadorian protests', 'The 2019 Ecuadorian protests were a series of protests and riots against austerity measures including the cancellation of fuel subsidies, adopted by President of Ecuador Lenín Moreno and his administration. Organized protests ceased after indigenous groups and the Ecuadorian government reached a deal to reverse the austerity measures, beginning a collaboration on how to combat overspending and public debt.', 2019, 10, 3, 2019, 10, 14, 'day', '3 October 2019 – 14 October 2019', 56, 'https://en.wikipedia.org/wiki/2019_Ecuadorian_protests'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q105659414', 'February 2021 Ecuadorian prison riots', 'On 23 February 2021, 79 inmates were killed and several others were injured in riots that took place simultaneously in four Ecuadorian prisons. Authorities have cited gang rivalry in an overcrowded prison system as the cause.', 2021, 2, 23, NULL, NULL, NULL, 'day', '23 February 2021', 34, 'https://en.wikipedia.org/wiki/February_2021_Ecuadorian_prison_riots'),
  ('Q108748542', 'September 2021 Guayaquil prison riot', 'The September 2021 Guayaquil prison riot occurred at the Litoral Penitentiary in Guayaquil, Ecuador on 28 September 2021. At least 123 inmates were killed and several others were injured in the riot that took place in that prison.', 2021, 9, 28, NULL, NULL, NULL, 'day', '28 September 2021', 34, 'https://en.wikipedia.org/wiki/September_2021_Guayaquil_prison_riot'),
  ('Q109568693', 'November 2021 Guayaquil prison riot', 'The November 2021 Guayaquil prison riot occurred on 13 November 2021 at the Litoral Penitentiary in Guayaquil, Ecuador, killing at least 68 people and injuring 25.', 2021, 11, 12, 2021, 11, 13, 'day', '12 November 2021 – 13 November 2021', 34, 'https://en.wikipedia.org/wiki/November_2021_Guayaquil_prison_riot'),
  ('Q109783491', '2021 Amazonas earthquake', 'A major earthquake struck northern Peru on November 28, 2021, 5:52 a.m. local time with a magnitude of 7.5 on the moment magnitude scale between the Amazonas and Loreto departments of Peru.', 2021, 11, 28, NULL, NULL, NULL, 'day', '28 November 2021', 43, 'https://en.wikipedia.org/wiki/2021_Northern_Peru_earthquake'),
  ('Q117202252', '2023 Guayas earthquake', 'A strong earthquake struck southern Ecuador on 18 March 2023. It measured 6.8 on the moment magnitude scale, and struck with a hypocenter 68.0 km (42.3 mi) deep.', 2023, 3, 18, NULL, NULL, NULL, 'day', '18 March 2023', 50, 'https://en.wikipedia.org/wiki/2023_Guayas_earthquake'),
  ('Q121334219', 'Assassination of Fernando Villavicencio', 'On 9 August 2023, eleven days before the 2023 Ecuadorian general election, presidential candidate Fernando Villavicencio was assassinated after leaving a campaign rally in Quito, the capital of Ecuador. One assailant was killed during the attack.', 2023, 8, 9, NULL, NULL, NULL, 'day', '9 August 2023', 43, 'https://en.wikipedia.org/wiki/Assassination_of_Fernando_Villavicencio'),
  ('Q124221028', '2024 Ecuadorian conflict', 'On 9 January 2024, an armed conflict broke out in Ecuador involving the country''s government against several organized crime groups, most notably the Los Choneros cartel. Reports of armed attacks throughout Guayaquil and other parts of the country were widespread, occurring primarily in prisons, markets, roads, and universities.', 2024, 1, 9, 2025, 7, 20, 'day', '9 January 2024 – 20 July 2025', 62, 'https://en.wikipedia.org/wiki/Ecuadorian_conflict_(2024%E2%80%93present)');
